import { Chat } from "@ai-sdk/react"
import { trpcClient } from "../../../lib/trpc"
import {
  createRuntimeRouteTransport,
  type RuntimeRouteTransportInput,
} from "../lib/runtime-route-transport"

type BindingRead = {
  status: "pending" | "error" | "success"
  binding?: { transportId?: string } | null
}

function toRouteTransportInput(read: BindingRead): RuntimeRouteTransportInput {
  if (read.status === "error") return { state: "error" }
  const transportId = read.binding?.transportId
  if (read.status !== "success" || !transportId) return { state: "not-loaded" }
  return { state: "loaded", transportId }
}

export function useRuntimeRouteChats(ctx: ChatSiteContext) {
  const getOrCreateChat = (subChatId: string): Chat<unknown> | null => {
    const existing = ctx.agentChatStore.get(subChatId)
    if (existing) return existing
    const subChat = ctx.subChats.find((candidate) => candidate.id === subChatId)
    const binding = subChat?.binding
    if (!binding) return null
    const route = createRuntimeRouteTransport(
      toRouteTransportInput({ status: ctx.chatQuery.status, binding }),
      { chatId: ctx.chatId, subChatId, binding, projectPath: ctx.projectPath, mode: ctx.mode },
    )
    if (!route.ok) {
      ctx.setRouteFailure(subChatId, route.failure)
      return null
    }
    const newChat = new Chat({ id: subChatId, messages: subChat.messages, transport: route.transport })
    ctx.agentChatStore.set(subChatId, newChat)
    return newChat
  }

  const createNewSubChat = async (): Promise<void> => {
    let created: { id: string; binding: { transportId?: string } }
    try {
      created = await trpcClient.chats.createSubChat.mutate({
        chatId: ctx.chatId,
        mode: ctx.mode,
        binding: ctx.newBinding,
      })
    } catch {
      const failed = createRuntimeRouteTransport(
        toRouteTransportInput({ status: "error" }),
        { chatId: ctx.chatId, subChatId: "", binding: ctx.newBinding, projectPath: ctx.projectPath, mode: ctx.mode },
      )
      if (!failed.ok) ctx.setRouteFailure(ctx.chatId, failed.failure)
      return
    }
    const route = createRuntimeRouteTransport(
      toRouteTransportInput({ status: "success", binding: created.binding }),
      { chatId: ctx.chatId, subChatId: created.id, binding: created.binding, projectPath: ctx.projectPath, mode: ctx.mode },
    )
    if (!route.ok) {
      ctx.setRouteFailure(created.id, route.failure)
      return
    }
    const newChat = new Chat({ id: created.id, messages: [], transport: route.transport })
    ctx.agentChatStore.set(created.id, newChat)
  }

  return { getOrCreateChat, createNewSubChat }
}

