import { CodexAppServerChatTransport } from "./codex-app-server-chat-transport"
import { IPCChatTransport } from "./ipc-chat-transport"

export type RuntimeRouteTransportInput =
  | { state: "loaded"; transportId: string }
  | { state: "not-loaded" }
  | { state: "error" }

export type RuntimeRouteTransportFailure =
  | "route_descriptor_unavailable"
  | "route_descriptor_error"
  | "unknown_transport"

type RouteTransportConfig = ConstructorParameters<typeof IPCChatTransport>[0]
type RouteTransport = IPCChatTransport | CodexAppServerChatTransport

const TRANSPORT_CONSTRUCTORS: Readonly<
  Record<string, (config: RouteTransportConfig) => RouteTransport>
> = {
  "claude-chat-ipc": (config) => new IPCChatTransport(config),
  "codex-chat-ipc": (config) => new CodexAppServerChatTransport(config),
}

export function createRuntimeRouteTransport(
  input: RuntimeRouteTransportInput,
  config: RouteTransportConfig,
):
  | { ok: true; transport: RouteTransport }
  | { ok: false; failure: RuntimeRouteTransportFailure } {
  if (input.state === "error") {
    return { ok: false, failure: "route_descriptor_error" }
  }
  if (input.state !== "loaded") {
    return { ok: false, failure: "route_descriptor_unavailable" }
  }
  const construct = TRANSPORT_CONSTRUCTORS[input.transportId]
  if (!construct) return { ok: false, failure: "unknown_transport" }
  return { ok: true, transport: construct(config) }
}

import { CodexAppServerChatTransport } from "./codex-app-server-chat-transport"
import { IPCChatTransport } from "./ipc-chat-transport"

export type RuntimeRouteTransportInput =
  | { state: "loaded"; transportId: string }
  | { state: "not-loaded" }
  | { state: "error" }

export type RuntimeRouteTransportFailure =
  | "route_descriptor_unavailable"
  | "route_descriptor_error"
  | "unknown_transport"

type RouteTransportConfig = ConstructorParameters<typeof IPCChatTransport>[0]
type RouteTransport = IPCChatTransport | CodexAppServerChatTransport

const TRANSPORT_CONSTRUCTORS: Readonly<
  Record<string, (config: RouteTransportConfig) => RouteTransport>
> = {
  "claude-chat-ipc": (config) => new IPCChatTransport(config),
  "codex-chat-ipc": (config) => new CodexAppServerChatTransport(config),
}

export function createRuntimeRouteTransport(
  input: RuntimeRouteTransportInput,
  config: RouteTransportConfig,
):
  | { ok: true; transport: RouteTransport }
  | { ok: false; failure: RuntimeRouteTransportFailure } {
  if (input.state === "error") {
    return { ok: false, failure: "route_descriptor_error" }
  }
  if (input.state !== "loaded") {
    return { ok: false, failure: "route_descriptor_unavailable" }
  }
  if (config.binding.runtime === "codex") {
    return { ok: true, transport: new CodexAppServerChatTransport(config) }
  }
  const construct = TRANSPORT_CONSTRUCTORS[input.transportId]
  if (!construct) return { ok: true, transport: new IPCChatTransport(config) }
  return { ok: true, transport: construct(config) }
}

import { withRuntimeRouteTransportId } from "../../agent-runtime/runtime-route-read-model"
import { type ChatSessionBindingExecutor, getSubChatBinding } from "../../chat-session-binding"

export function readSubChatBindingReadModel(
  db: ChatSessionBindingExecutor,
  subChatId: string,
) {
  return withRuntimeRouteTransportId(getSubChatBinding(db, subChatId))
}

import { type ChatSessionBindingExecutor, getSubChatBinding } from "../../chat-session-binding"

const TRANSPORT_ID_BY_RUNTIME = {
  "claude-code": "claude-chat-ipc",
  codex: "codex-chat-ipc",
} as const

export function readSubChatBindingReadModel(
  db: ChatSessionBindingExecutor,
  subChatId: string,
) {
  const binding = getSubChatBinding(db, subChatId)
  return { ...binding, transportId: TRANSPORT_ID_BY_RUNTIME[binding.runtime] }
}
